    """
    Find two indices i < j such that nums[i] + nums[j] == target.
    Returns the pair (i, j) with smallest j, then smallest i.
    Returns None if no such pair exists.
    """
    n = len(nums)

    # Iterate through all pairs (i, j) with i < j
    # We want smallest j first, then smallest i
    # So we iterate j from 1 to n-1, and for each j, i from 0 to j-1
    for j in range(1, n):
        for i in range(j):
            if nums[i] + nums[j] == target:
                return (i, j)

    return None

