def caesar(text, shift):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            offset = ord('a')
            shifted = chr((ord(char) - offset + shift) % 26 + offset)
            result.append(shifted)
        elif 'A' <= char <= 'Z':
            offset = ord('A')
            shifted = chr((ord(char) - offset + shift) % 26 + offset)
            result.append(shifted)
        else:
            result.append(char)
    return ''.join(result)

def caesar(text, shift):
    result = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = (ord(char) - base + shift) % 26
            result.append(chr(base + shifted))
        else:
            result.append(char)
    return ''.join(result)

def caesar(text, shift):
    def shift_char(c):
        if 'A' <= c <= 'Z':
            return chr(ord('A') + (ord(c) - ord('A') + shift) % 26)
        elif 'a' <= c <= 'z':
            return chr(ord('a') + (ord(c) - ord('a') + shift) % 26)
        return c

    return ''.join(shift_char(c) for c in text)

def is_balanced(s):
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    open_brackets = set(matching.values())

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False
    return not stack

def is_balanced(s):
