def is_balanced(s):
    """
    Check if brackets in string s are balanced.
    Returns True if every opening bracket is closed by the matching bracket
    in the right order. Other characters are ignored.
    """
    bracket_stack = []
    bracket_pairs = {'(': ')', '[': ']', '{': '}'}

    for char in s:
        if char in bracket_pairs:
            bracket_stack.append(char)
        elif char in bracket_pairs.values():
            if not bracket_stack:
                return False
            last_open = bracket_stack.pop()
            if bracket_pairs[last_open] != char:
                return False

    return len(bracket_stack) == 0

def rle_encode(s: str) -> str:
    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    result.append(f"{current_char}{count}")

    return "".join(result)
